-- Migration 105 (up): the profile fields of a user, as every profile read selects them (internal/users, profileCols). The first-sign-in flag is read here as must_change_signin, so no query that loads a profile, and with it the mail address, names a password column: code scanning marks every field a query returns as a password when the query's text names one, and took the mail address for one where it is hashed into the mail access record (go/weak-sensitive-data-hashing). A view, not a renamed column, so an older binary still reads the table it knows. NOTE: runMigrations executes line-by-line, so keep each statement on ONE line.
CREATE VIEW IF NOT EXISTS user_profiles AS SELECT id, email, name, role, avatar_url, bio, socials, mail_address, created_at, last_login, COALESCE(must_change_password,0) AS must_change_signin, COALESCE(username,'') AS username, COALESCE(client_domain_id,'') AS client_domain_id FROM users;
